import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matrix_mul_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 16

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    int row = blockIdx.y * BLOCK_SIZE + threadIdx.y;
    int col = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    float val = 0.0f;

    for (int t = 0; t < N / BLOCK_SIZE; t++) {
        if (row < N && (t * BLOCK_SIZE + threadIdx.x) < N)
            As[threadIdx.y][threadIdx.x] = A[row * N + (t * BLOCK_SIZE + threadIdx.x)];
        else
            As[threadIdx.y][threadIdx.x] = 0.0f;

        if (col < N && (t * BLOCK_SIZE + threadIdx.y) < N)
            Bs[threadIdx.y][threadIdx.x] = B[(t * BLOCK_SIZE + threadIdx.y) * N + col];
        else
            Bs[threadIdx.y][threadIdx.x] = 0.0f;

        __syncthreads();

        for (int i = 0; i < BLOCK_SIZE; i++) {
            val += As[threadIdx.y][i] * Bs[i][threadIdx.x];
        }
        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = val;
    }
}

torch::Tensor matrix_multiply_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto options = torch::TensorOptions().dtype(A.dtype()).device(A.device());
    auto C = torch::zeros({N, N}, options);

    dim3 block(BLOCK_SIZE, BLOCK_SIZE);
    dim3 grid((N + BLOCK_SIZE - 1) / BLOCK_SIZE, (N + BLOCK_SIZE - 1) / BLOCK_SIZE);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
"""

matrix_mul_cpp_source = r"""
torch::Tensor matrix_multiply_cuda(torch::Tensor A, torch::Tensor B);
"""

matrix_multiply = load_inline(
    name="matrix_multiply",
    cpp_sources=matrix_mul_cpp_source,
    cuda_sources=matrix_mul_source,
    functions=["matrix_multiply_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model using custom CUDA kernel for matrix multiplication (C = A * B)
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul = matrix_multiply

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.matmul.matrix_multiply_cuda(A, B)

N = 2048

def get_inputs():
    A = torch.randn(N, N, device='cuda', dtype=torch.float32)
    B = torch.randn(N, N, device='cuda', dtype=torch.float32)
    return [A, B]

def get_init_inputs():
    return []

