from torch.utils.cpp_extension import load_inline

matmul_optimized_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 32

__global__ void matmul_optimized_kernel(const float* A, const float* B, float* C,
                                        int N) {
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    int row = blockIdx.y * BLOCK_SIZE + threadIdx.y;
    int col = blockIdx.x * BLOCK_SIZE + threadIdx.x;

    float value = 0.0f;

    for (int m = 0; m < N; m += BLOCK_SIZE) {
        // Load data to shared memory
        if (row < N && (m + threadIdx.x) < N)
            As[threadIdx.y][threadIdx.x] = A[row * N + (m + threadIdx.x)];
        else
            As[threadIdx.y][threadIdx.x] = 0.0f;

        if (col < N && (m + threadIdx.y) < N)
            Bs[threadIdx.y][threadIdx.x] = B[(m + threadIdx.y) * N + col];
        else
            Bs[threadIdx.y][threadIdx.x] = 0.0f;

        __syncthreads();

        #pragma unroll 8
        for (int k = 0; k < BLOCK_SIZE; k++) {
            value += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = value;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Ensure inputs are on CUDA
    A = A.contiguous();
    B = B.contiguous();

    int N = A.size(0);

    auto options = torch::TensorOptions().dtype(A.dtype()).device(A.device());
    auto C = torch::zeros({N, N}, options);

    dim3 threads(BLOCK_SIZE, BLOCK_SIZE);
    dim3 blocks((N + BLOCK_SIZE - 1) / BLOCK_SIZE, (N + BLOCK_SIZE - 1) / BLOCK_SIZE);

    matmul_optimized_kernel<<<blocks, threads>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
